const approval = $('Notion Get Approval').first().json;
const rules = $('Notion Estimate Rules').all().map(i => i.json);
const P = approval.properties || {};
const rt = v => (v && (v.rich_text || v.title) || []).map(t => t.plain_text).join('');
const sel = v => (v && v.select && v.select.name) || '';
const type = sel(P['Type']);
const draft = rt(P['Draft']);
const context = rt(P['Title']) + '\n' + rt(P['Related Job']);
const failures = [], manual = [];
const fail = (id, msg) => failures.push(id + ': ' + msg);
const norm = s => String(s || '').replace(/-/g, '').toLowerCase();
const key = s => String(s || '').trim().replace(/\s+/g, ' ').toLowerCase();
const cents = n => Math.round((Number(n) + Number.EPSILON) * 100);
const isNum = n => typeof n === 'number' && isFinite(n);
const twoDp = n => isNum(n) && Math.abs(n * 100 - Math.round(n * 100)) < 1e-6;

if (!draft.trim()) fail('EMPTY', 'Draft is empty');

if (type === 'Estimate' && draft.trim()) {
  const R = rules.map(r => {
    const p = r.properties || {};
    return { id: norm(r.id), service: rt(p['Service']), category: sel(p['Category']), unit: sel(p['Unit']),
      base: p['Base Rate'] ? p['Base Rate'].number : null, min: p['Minimum Charge'] ? p['Minimum Charge'].number : null,
      active: p['Active'] ? p['Active'].checkbox === true : false, notes: rt(p['Notes']) };
  });
  let d = null;
  try {
    const mk = draft.indexOf('[estimate-json]');
    if (mk >= 0) {
      d = JSON.parse(draft.slice(mk + '[estimate-json]'.length).trim());
    } else {
      const raw = draft.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
      const m = raw.match(/\{[\s\S]*\}/);
      d = JSON.parse(m ? m[0] : raw);
    }
  } catch (e) { d = null; }
  if (!d || typeof d !== 'object' || Array.isArray(d)) {
    fail('E1', 'Draft is not a valid JSON object');
  } else {
    if (!['draft', 'needs_info'].includes(d.status)) fail('E1', 'status must be draft or needs_info');
    if (!Array.isArray(d.line_items)) fail('E1', 'line_items missing or not a list');
    if (!Array.isArray(d.missing_fields)) fail('E1', 'missing_fields missing or not a list');
    if (!Array.isArray(d.rule_notes)) fail('E1', 'rule_notes missing or not a list');
    const items = Array.isArray(d.line_items) ? d.line_items : [];
    const used = [];
    let sumLine = 0, primSum = 0, addSum = 0, maxMin = null, hasPrim = false, hasAdd = false, priced = true;
    items.forEach((li, n) => {
      const tag = 'line ' + (n + 1) + ' (' + (li && li.service) + ')';
      if (!li || typeof li !== 'object') { fail('E1', tag + ' is not an object'); priced = false; return; }
      for (const f of ['service', 'rule_id', 'category', 'unit', 'base_rate', 'quantity', 'computed', 'minimum_charge', 'line_total'])
        if (li[f] === undefined || li[f] === null) fail('E1', tag + ' missing field ' + f);
      const matches = R.filter(r => r.id === norm(li.rule_id));
      if (!matches.length) { fail('E2', tag + ' rule_id not found in Estimate Rules'); priced = false; return; }
      const r = matches[0];
      if (!r.active) fail('E2', tag + ' rule is not Active');
      if (key(r.service) !== key(li.service)) fail('E3', tag + ' service differs from rule "' + r.service + '"');
      if (r.category !== li.category) fail('E3', tag + ' category differs from rule (' + r.category + ')');
      if (r.unit !== li.unit) fail('E3', tag + ' unit differs from rule (' + r.unit + ')');
      if (r.base === null || Number(li.base_rate) !== r.base) fail('E3', tag + ' base_rate differs from rule (' + r.base + ')');
      if ((r.min === null ? 0 : r.min) !== Number(li.minimum_charge || 0)) fail('E3', tag + ' minimum_charge differs from rule (' + r.min + ')');
      if (r.base === null) { priced = false; return; }
      used.push(r);
      const q = li.quantity;
      if (!isNum(q) || q < 0) { fail('E4', tag + ' quantity is not a non-negative number'); priced = false; return; }
      if (r.unit === 'Flat Rate' && q !== 1) fail('E4', tag + ' flat rate quantity must be 1');
      const comp = cents(r.base * q) / 100;
      if (!isNum(li.computed) || cents(li.computed) !== cents(comp)) fail('E5', tag + ' computed should be ' + comp.toFixed(2));
      const isPrim = r.category === 'Interior' || r.category === 'Exterior';
      let expLine = comp, minApplied = false;
      if (isPrim && r.min !== null && comp < r.min) { expLine = r.min; minApplied = true; }
      if (!isNum(li.line_total) || cents(li.line_total) !== cents(expLine)) fail('E5', tag + ' line_total should be ' + expLine.toFixed(2));
      if (li.minimum_applied !== minApplied) fail('E5', tag + ' minimum_applied should be ' + minApplied);
      for (const f of ['base_rate', 'computed', 'minimum_charge', 'line_total'])
        if (isNum(li[f]) && !twoDp(li[f])) fail('E5', tag + ' ' + f + ' not rounded to 2 decimals');
      sumLine += cents(li.line_total || 0);
      if (isPrim) { hasPrim = true; primSum += cents(comp); if (r.min !== null && (maxMin === null || cents(r.min) > maxMin)) maxMin = cents(r.min); }
      else { hasAdd = true; addSum += cents(comp); }
    });
    // E6 / E9 totals (estimate.py: minimum applies to the primary subtotal, add-ons excluded)
    if (d.status === 'needs_info') {
      if (d.subtotal !== null || d.total !== null) fail('E9', 'needs_info requires subtotal and total to be null');
    } else if (d.status === 'draft') {
      if (Array.isArray(d.missing_fields) && d.missing_fields.length) fail('E9', 'draft must have empty missing_fields');
      if (!items.length) fail('E6', 'draft has no line items');
      if (priced && items.length) {
        const expSub = primSum + addSum;
        const expTot = (hasPrim && maxMin !== null && primSum < maxMin ? maxMin : primSum) + addSum;
        if (!isNum(d.total) || cents(d.total) !== expTot) fail('E6', 'total should be ' + (expTot / 100).toFixed(2) + ' (estimate.py rules)');
        if (!isNum(d.subtotal) || (cents(d.subtotal) !== sumLine && cents(d.subtotal) !== expSub)) fail('E6', 'subtotal does not match the sum of lines');
        if (isNum(d.total) && cents(d.total) !== sumLine) fail('E6', 'total does not equal the sum of line_totals');
      }
    }
    if (hasAdd && !hasPrim) fail('E8', 'Add-On line(s) without an Interior/Exterior main service');
    // E10 duplicate Active rules
    const seen = new Set();
    for (const r of used) {
      const k = key(r.service);
      if (seen.has(k)) continue;
      seen.add(k);
      if (R.filter(x => x.active && key(x.service) === k).length > 1) fail('E10', 'more than one Active rule matches "' + r.service + '"');
    }
    // E11 rule notes
    const rn = (Array.isArray(d.rule_notes) ? d.rule_notes : []).map(x => typeof x === 'string' ? x : JSON.stringify(x)).join('\n');
    for (const r of used) if (r.notes && !rn.includes(r.notes.trim())) fail('E11', 'rule_notes missing Notes of "' + r.service + '"');
    if (used.some(r => r.notes)) manual.push('E11: confirm conditions in rule Notes are satisfied or listed as missing');
    if (d.needs_human !== true) fail('E14', 'needs_human must be true');
    const clientText = JSON.stringify([d.assumptions, d.rule_notes, d.missing_fields]);
    if (/sk-[A-Za-z0-9]{10,}|secret|password|api[_ -]?key|\b(?:\d[ -]?){13,16}\b/i.test(clientText)) fail('E13', 'possible secret or card number in client-visible text');
  }
  manual.push('E4: quantities match the intake (sqft / rooms / hours)');
  manual.push('E7: every requested service has a line or a missing_fields entry; no unrequested lines');
  manual.push('E12: assumptions contain no facts absent from intake');
  manual.push('E13: no internal rule-problem text in client-visible fields');
} else if (type === 'Estimate') {
  // empty draft already failed
} else if (type === 'Reply' || type === 'Content') {
  if (draft.trim() && draft.trim().length < 10) fail('R1', 'Draft is too short to be real content');
  const ph = draft.match(/REPLACE_[A-Z0-9_]*|\bTODO\b|\bTBD\b|\bFIXME\b|lorem ipsum|\[\s*(?:name|insert|your|client)[^\]]*\]|\{\{[^}]*\}\}|<[A-Z_ ]{3,}>/i);
  if (ph) fail('R2', 'placeholder text found: ' + ph[0]);
  const money = draft.match(/\$\s?\d[\d,.]*|\b\d+(?:\.\d+)?\s?%\s*off\b|\bdiscounts?\b|\bcoupon\b|\bpromo(?:tion)? code\b|\bprice match\b|\bguarantee[sd]?\b|\bfree of charge\b|\bcomplimentary\b/i);
  if (money) fail('R3', 'price or discount commitment: ' + money[0]);
  const ctx = context.toLowerCase();
  const emails = draft.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];
  for (const e of emails) if (!ctx.includes(e.toLowerCase())) fail('R4', 'email not found in item context: ' + e);
  const digits = s => s.replace(/\D/g, '').replace(/^1(?=\d{10}$)/, '');
  const ctxDigits = digits(context);
  const phones = draft.match(/(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}/g) || [];
  for (const ph2 of phones) if (!ctxDigits.includes(digits(ph2))) fail('R4', 'phone number not found in item context: ' + ph2);
  manual.push('Tone, accuracy of facts and client-appropriateness need human review');
} else {
  fail('TYPE', 'Approval Type must be Estimate, Reply or Content (got "' + type + '")');
}
const result = failures.length ? 'Fail' : 'Pass';
return [{ json: { approval_id: approval.id, type, result, failures, manual_checks: manual } }];
